// Pasted images (every-agent-field-takes-images, invariant 97): the caps and refusals, the image store, the queue
// carrying refs (never bytes) and sending each image exactly once, dispatch handing them to agents.create, the one
// image-support rule, and an agent tool's file checks. Fixtures are generated bytes, never anything from the machine.
import test, { type TestContext } from "node:test";
import assert from "node:assert/strict";
import { chmod, mkdtemp, mkdir, readdir, readFile, stat, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { rm, testStore, trackPersistence } from "./support/store-temp-dir";
import { FakeTimers } from "./support/fake-timers";
import { MAX_IMAGE_BYTES, MAX_IMAGES, base64Bytes, imageRefusal, imageUploadsSchema, imagesPlanLine, sniffImageType, WRONG_TYPE } from "../shared/images";
import { queueFileSchema } from "../shared/queue";
import { ImageStore, readImageFile, readImageFiles } from "../server/image-store";
import { imageSupport } from "../server/image-support";
import { MessageQueue, QUEUE_FILE, type Courier } from "../server/message-queue";
import { DispatchService, DispatchStore, type DispatchDeps, type DispatchPaseo } from "../server/dispatch";

const PNG = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";
const png = (name = "acme-dashboard.png") => ({ name, mimeType: "image/png" as const, data: PNG });

async function dir(t: TestContext, prefix: string) {
  const d = await mkdtemp(join(tmpdir(), prefix));
  t.after(() => rm(d, { recursive: true, force: true }));
  return d;
}

test("caps and refusals: the plain sentence for each, before anything is read", () => {
  const small = { bytes: 1000, mimeType: "image/png" };
  assert.equal(imageRefusal([], [small]), null);
  assert.equal(imageRefusal(Array(MAX_IMAGES).fill(small), [small]), "6 images is the most one message takes.");
  assert.equal(imageRefusal([], [{ bytes: 7.2 * 1024 * 1024, mimeType: "image/png" }]), "That image is 7.2 MB; the most is 5 MB.");
  assert.equal(imageRefusal([], [{ bytes: 1000, mimeType: "image/svg+xml" }]), WRONG_TYPE);
  assert.equal(imageRefusal([{ bytes: 4.2 * 1024 * 1024 }, { bytes: 4.2 * 1024 * 1024 }, { bytes: 4.2 * 1024 * 1024 }, { bytes: 4.2 * 1024 * 1024 }], [{ bytes: 4.2 * 1024 * 1024, mimeType: "image/jpeg" }]),
    "These images add up to 21 MB; the most one message takes is 20 MB.");
  // The RPC schema holds the same caps, from the base64 length.
  assert.equal(base64Bytes(PNG), Buffer.from(PNG, "base64").length);
  assert.throws(() => imageUploadsSchema.parse(Array(MAX_IMAGES + 1).fill(png())), /6 images is the most/);
  assert.throws(() => imageUploadsSchema.parse([{ ...png(), data: "A".repeat(Math.ceil(MAX_IMAGE_BYTES / 3) * 4 + 8) }]));
  assert.equal(imagesPlanLine([{ name: "a.png", bytes: 1024 * 1024 }]), "With an image: a.png (1 MB).");
});

test("an image's type comes from its first bytes, never its name", () => {
  assert.equal(sniffImageType(Buffer.from(PNG, "base64")), "image/png");
  assert.equal(sniffImageType(Buffer.from([0xff, 0xd8, 0xff, 0xe0])), "image/jpeg");
  assert.equal(sniffImageType(Buffer.from("GIF89a")), "image/gif");
  assert.equal(sniffImageType(Buffer.concat([Buffer.from("RIFF"), Buffer.alloc(4), Buffer.from("WEBP")])), "image/webp");
  assert.equal(sniffImageType(Buffer.from("<svg></svg>")), null);
});

test("the store writes 0600 files under images/, reads them back as base64, removes them, and sweeps orphans", async t => {
  const root = await dir(t, "images-store-");
  const store = new ImageStore(root);
  const [a, b] = await store.save([png("one.png"), png("two.png")]);
  assert.ok(a && b);
  const info = await stat(join(root, "images", `${a.id}.png`));
  assert.equal(info.mode & 0o777, 0o600);
  assert.deepEqual(await store.read([a]), [{ data: PNG, mimeType: "image/png" }]);
  await store.remove([a]);
  assert.deepEqual(await store.read([a]), [], "a missing file is left out, never a failed send");
  assert.equal(await store.sweep([]), 1, "b is referenced by nothing: swept");
  assert.deepEqual(await readdir(join(root, "images")), []);
  // A file whose bytes aren't what it says is refused, and nothing is kept.
  await assert.rejects(store.save([{ name: "fake.png", mimeType: "image/png", data: Buffer.from("not an image").toString("base64") }]), /Only PNG/);
  assert.deepEqual(await readdir(join(root, "images")), []);
});

function imageQueue(root: string, o: { deliver?: Courier["deliverTo"] } = {}) {
  const sent: { text: string; messageId: string; images?: { data: string; mimeType: string }[] }[] = [];
  const store = new ImageStore(root);
  const courier: Courier = {
    deliverTo: async (target, text, messageId, by, images) => { const r = o.deliver ? await o.deliver(target, text, messageId, by, images) : target.recipients[0]!; sent.push({ text, messageId, images }); return r; },
    arrived: async (_a, id) => sent.some(s => s.messageId === id),
  };
  const queue = trackPersistence(root, new MessageQueue(root, courier, { writeMs: 0, images: store }));
  const timers = new FakeTimers();
  queue.timers = timers; queue.now = () => Date.parse("2026-11-23T09:00:00.000Z") + timers.now; queue.quietMs = 0; queue.capMs = 0;
  queue.register("message", { resolve: async item => ({ target: { workspaceId: null, recipients: [item.ref.agentId!] } }), project: async () => undefined });
  return { queue, store, sent, timers };
}

test("a queued message keeps refs in queue.json, sends its images exactly once, and removes the files once delivered", async t => {
  const root = await dir(t, "images-queue-");
  const { queue, store, sent } = imageQueue(root);
  t.after(() => queue.stop());
  await queue.load();
  const refs = await store.save([png()]);
  queue.enqueue({ id: "message:a1:m1", kind: "message", key: "agent:a1", ref: { agentId: "a1" }, messageId: "m1", text: "From the developer via Overseer: see the screenshot", images: refs, priority: "now", state: "queued" });
  await queue.flush();
  const file = queueFileSchema.parse(JSON.parse(await readFile(join(root, QUEUE_FILE), "utf8")));
  assert.deepEqual(file.items[0]!.images, refs, "refs in queue.json");
  assert.doesNotMatch(await readFile(join(root, QUEUE_FILE), "utf8"), new RegExp(PNG.slice(0, 20)), "never the bytes");
  assert.deepEqual(queue.imageIds(), refs.map(r => r.id));
  queue.start(); await queue.idle();
  assert.equal(sent.length, 1);
  assert.deepEqual(sent[0]!.images, [{ data: PNG, mimeType: "image/png" }]);
  assert.deepEqual(await readdir(join(root, "images")), [], "delivered: the file is gone");
  assert.deepEqual(queue.list().recent.at(-1)!.images, [], "the settled copy keeps no refs");
});

test("a send that may have left keeps its images for the resend, and the same message again adds no copy", async t => {
  const root = await dir(t, "images-retry-");
  let calls = 0;
  const { queue, store, sent, timers } = imageQueue(root, { deliver: async target => { calls++; if (calls === 1) throw new Error("socket closed"); return target.recipients[0]!; } });
  t.after(() => queue.stop());
  await queue.load();
  const refs = await store.save([png()]);
  const item = { id: "message:a1:m2", kind: "message" as const, key: "agent:a1", ref: { agentId: "a1" }, messageId: "m2", text: "hello", images: refs, priority: "now" as const, state: "queued" as const };
  queue.enqueue(item);
  const again = await store.save([png()]);
  queue.enqueue({ ...item, images: again });
  queue.start(); await queue.idle();
  assert.equal((await readdir(join(root, "images"))).length, 1, "the double click's copy was removed; the item's own file stays for the resend");
  await timers.fire(); await queue.idle();
  assert.equal(calls, 2);
  assert.deepEqual(sent.map(s => s.images?.length), [1], "the resend carries the image, once (the first never confirmed)");
  assert.deepEqual(await readdir(join(root, "images")), []);
});

function fakePaseo() {
  const agents: Record<string, unknown>[] = [];
  const paseo: DispatchPaseo = { workspaces: { create: async () => ({ id: "ws-1", agents: { create: async a => { agents.push(a); return { id: "agent-1" }; } } }), archive: async () => undefined } };
  return { paseo, agents };
}

test("New's images go with the new agent's first message (agents.create), then their files are removed", async t => {
  const root = await dir(t, "images-dispatch-");
  const fake = fakePaseo();
  const images = new ImageStore(root);
  const deps: DispatchDeps = {
    store: testStore(DispatchStore, root),
    linear: { list: async () => ({ status: "ok", issues: [], at: 0, more: false }), get: async () => null, search: async () => ({ status: "ok", issues: [], at: 0, more: false }) },
    projects: async () => [{ id: "web", name: "web", repo: "acme/web", worktree: true, path: "/work/web" }],
    learned: async () => ({}), existing: async () => null, defaultBase: async () => "main",
    agent: async () => ({ config: { provider: "claude" }, label: "Claude" }), multiplicity: async () => true,
    paseo: async () => fake.paseo, images, now: () => Date.parse("2026-11-23T09:00:00.000Z"),
  };
  const service = new DispatchService(deps);
  t.after(() => service.stop());
  const { record } = await service.dispatch({ source: "Fix the acme dashboard chart, see the screenshot", projectId: "web", images: [png(), png("second.png")] });
  assert.equal(record.images?.length, 2);
  assert.deepEqual(await service.imageIds(), record.images!.map(i => i.id), "a waiting dispatch keeps its images through a restart's sweep");
  await service.settle();
  assert.deepEqual(fake.agents[0]!.images, [{ data: PNG, mimeType: "image/png" }, { data: PNG, mimeType: "image/png" }]);
  assert.deepEqual(await readdir(join(root, "images")), [], "created: the files are gone");
  const [done] = await service.records();
  assert.deepEqual([done!.state, done!.images ?? []], ["created", []]);
});

test("one rule decides who takes images: built-in providers yes, an unknown one says so by name", () => {
  assert.equal(imageSupport({ provider: "claude/opus" }).ok, true);
  assert.equal(imageSupport({ provider: "codex" }).ok, true);
  assert.deepEqual(imageSupport({ provider: "acme-acp", providerLabel: "Acme Agent" }), { ok: false, provider: "Acme Agent", reason: "Acme Agent can't take images; remove them to send." });
  assert.equal(imageSupport({ provider: "acme-acp", capabilities: ["prompt.message", "prompt.image"] }).ok, true, "a host that reports prompt.image is believed");
  assert.equal(imageSupport(null).ok, false);
});

test("an agent tool's image is a readable regular image file under the cap, or it is refused with the reason", async t => {
  const root = await dir(t, "images-tool-");
  await writeFile(join(root, "acme.png"), Buffer.from(PNG, "base64"));
  await writeFile(join(root, "notes.png"), "just text");
  await writeFile(join(root, "huge.png"), Buffer.concat([Buffer.from(PNG, "base64"), Buffer.alloc(MAX_IMAGE_BYTES)]));
  await mkdir(join(root, "folder.png"));
  await symlink(join(root, "acme.png"), join(root, "link.png"));
  const ok = await readImageFile(join(root, "acme.png"));
  assert.deepEqual([ok.name, ok.mimeType, ok.data], ["acme.png", "image/png", PNG]);
  await assert.rejects(readImageFile(join(root, "notes.png")), /notes\.png: Only PNG, JPEG, GIF and WebP images\./);
  await assert.rejects(readImageFile(join(root, "huge.png")), /huge\.png is 5\.0 MB; the most is 5 MB\./);
  await assert.rejects(readImageFile(join(root, "folder.png")), /isn't a regular file/);
  await assert.rejects(readImageFile(join(root, "link.png")), /isn't a regular file/, "a symlink is not followed");
  await assert.rejects(readImageFile(join(root, "missing.png")), /no such file/);
  if (process.getuid?.() !== 0) {
    await writeFile(join(root, "locked.png"), Buffer.from(PNG, "base64")); await chmod(join(root, "locked.png"), 0o000);
    await assert.rejects(readImageFile(join(root, "locked.png")), /can't be read/);
  }
  await assert.rejects(readImageFiles(Array(MAX_IMAGES + 1).fill(join(root, "acme.png"))), /6 images is the most/);
  assert.equal(await readImageFiles(undefined), undefined);
});

test("an agent tool takes image paths: the plan names them by name and size, confirm sends the bytes, a bad file is refused at the dry run", async t => {
  const { AgentActions } = await import("../server/agent-actions");
  const root = await dir(t, "images-plan-");
  await writeFile(join(root, "acme-chart.png"), Buffer.from(PNG, "base64"));
  await writeFile(join(root, "readme.txt"), "text");
  const calls: { method: string; input: any }[] = [];
  const rpc = { validate: async (_m: string, i: unknown) => i, call: async (method: string, input: any) => { calls.push({ method, input }); return { ok: true }; } };
  const agent = new AgentActions({ store: { snapshot: async () => ({ version: 1, workspaces: [] }), mutate: async () => undefined }, inbox: { noteAction: async () => undefined }, rpc } as never);
  const plan = await agent.run("a1", "answer_question", { workspaceId: "w1", questionId: "Q1", choice: "A", images: [join(root, "acme-chart.png")] }) as { planId: string; images: string; change: { images: unknown[] } };
  assert.equal(plan.images, `With an image: acme-chart.png (0 MB).`.replace("0 MB", `${(base64Bytes(PNG) / 1024 / 1024).toFixed(1).replace(/\.0$/, "")} MB`));
  assert.deepEqual(plan.change.images, [{ name: "acme-chart.png", mimeType: "image/png", bytes: base64Bytes(PNG) }], "the plan shows no bytes");
  assert.equal(calls.length, 0, "the dry run sends nothing");
  await agent.run("a1", "answer_question", { confirm: true, planId: plan.planId });
  assert.deepEqual(calls[0]!.input.images, [{ name: "acme-chart.png", mimeType: "image/png", data: PNG }]);
  await assert.rejects(agent.run("a1", "answer_question", { workspaceId: "w1", questionId: "Q1", choice: "A", images: [join(root, "readme.txt")] }), /answer_question: readme\.txt: Only PNG/);
});
